"""Publish a sanitized review and any response generated by the graph."""

from ..state import ReviewState
from ..stores import PUBLISHED


def publish_review(state: ReviewState) -> dict[str, str]:
    entry = {"review_id": state["review"]["review_id"], "text": state["text"]}
    for key in ("reply", "answer"):
        if state.get(key):
            entry[key] = state[key]
    PUBLISHED.append(entry)
    return {"status": "published"}